// @domain: domains
//! #4995 (AC5) — the surfaces athena-make generates for a class, generated by athena-gen
//! for the API it builds: the MCP tool binding, the OpenAPI document and the page.
//! Each describes the routes the generated crate serves (`emit::routes`), never v1's.
//! Shapes follow athena-make's (mcp_binding, openapi_json, page_html) so the parity
//! check can compare them field by field and name every difference.

use crate::model::{Class, Kind, Product};

fn esc(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}

/// The collection route of `c` in the API `p` builds.
pub fn collection_route(p: &Product, domain: &str, c: &Class) -> String {
    if p.domain_unit { format!("/{domain}/{}", c.segment) } else { format!("/{}/{domain}/{}", p.name, c.segment) }
}

/// #4515 tool names: the runner serves athena-<verb> with the class named in the call
/// (ADR-031's chorus_<plural>_<verb> names were retired; nothing serves them), one per route.
pub fn mcp_json(p: &Product, domain: &str, c: &Class) -> String {
    let base = collection_route(p, domain, c);
    let tool = |verb: &str, route: String, extra: &str| {
        format!("{{ \"name\": \"athena-{verb}\", \"verb\": \"{verb}\", \"route\": \"{}\"{extra} }}", esc(&route))
    };
    let tools = [
        tool("list", format!("GET {base}"), ""),
        tool("get", format!("GET {base}/:name"), ""),
        tool("add", format!("POST {base}"), ", \"delegatesTo\": \"the generated door\""),
    ];
    format!(
        "{{\n  \"class\": \"{}\",\n  \"binding\": \"mcp\",\n  \"convention\": \"#4515 athena-<verb>, the class named in the call\",\n  \"tools\": [\n    {}\n  ]\n}}\n",
        esc(&c.name), tools.join(",\n    ")
    )
}

fn field_schema(f: &crate::model::Field) -> String {
    let one = match f.kind {
        Kind::Link { .. } => "{ \"$ref\": \"#/components/schemas/EdgeRef\" }".to_string(),
        Kind::Literal { .. } => "{ \"type\": \"string\" }".to_string(),
    };
    if f.many { format!("{{ \"type\": \"array\", \"items\": {one} }}") } else { one }
}

/// OpenAPI 3.1 for one class: the read schema, the create and replace bodies, and the
/// six routes the generated door serves (list, get, create, replace, patch, delete).
pub fn openapi_json(p: &Product, domain: &str, c: &Class) -> String {
    let base = collection_route(p, domain, c);
    // #5021 — the read schema says what a row carries: name, then the shape's fields (status only
    // when the shape declares it, as the door now serves it)
    let mut props: Vec<String> = vec!["\"name\": { \"type\": \"string\" }".into()];
    for f in &c.fields {
        props.retain(|x| !x.starts_with(&format!("\"{}\":", f.name)));
        props.push(format!("\"{}\": {}", f.name, field_schema(f)));
    }
    props.sort();
    let body = |f: &crate::model::Field| if f.many { "{ \"type\": \"array\", \"items\": { \"type\": \"string\" } }" } else { "{ \"type\": \"string\" }" };
    let mut replace_props: Vec<String> = c.fields.iter().filter(|f| f.name != "ownedBy").map(|f| format!("\"{}\": {}", f.name, body(f))).collect();
    replace_props.sort();
    let mut create_props = replace_props.clone();
    create_props.push("\"name\": { \"type\": \"string\" }".into());
    create_props.sort();
    let req = |extra: Option<&str>| {
        let mut r: Vec<String> = c.fields.iter().filter(|f| f.required && f.name != "ownedBy" && f.name != "label").map(|f| f.name.clone()).collect();
        if let Some(e) = extra { r.push(e.into()); }
        r.sort();
        r.dedup();
        r.iter().map(|n| format!("\"{n}\"")).collect::<Vec<_>>().join(", ")
    };
    let mut mandatory: Vec<String> = c.fields.iter().filter(|f| f.required).map(|f| format!("\"{}\"", f.name)).collect();
    mandatory.sort();
    let required = if mandatory.is_empty() { String::new() } else { format!(", \"required\": [{}]", mandatory.join(", ")) };
    let name_param = "\"parameters\": [ { \"name\": \"name\", \"in\": \"path\", \"required\": true, \"schema\": { \"type\": \"string\" } } ], ";
    let write = |m: &str, params: &str, schema: Option<String>| {
        let rb = schema.map(|s| format!("\"requestBody\": {{ \"required\": true, \"content\": {{ \"application/json\": {{ \"schema\": {s} }} }} }}, ")).unwrap_or_default();
        format!("\"{m}\": {{ {params}{rb}\"responses\": {{ \"200\": {{ \"description\": \"ok\" }}, \"201\": {{ \"description\": \"created\" }}, \"401\": {{ \"description\": \"authn-missing\" }}, \"403\": {{ \"description\": \"authz (ownedBy)\" }}, \"404\": {{ \"description\": \"not-found\" }}, \"409\": {{ \"description\": \"exists\" }}, \"422\": {{ \"description\": \"validation\" }}, \"503\": {{ \"description\": \"store unavailable\" }} }} }}")
    };
    let get = |params: &str, schema: &str| format!("\"get\": {{ {params}\"responses\": {{ \"200\": {{ \"description\": \"ok\", \"content\": {{ \"application/json\": {{ \"schema\": {{ \"$ref\": \"{schema}\" }} }} }} }}, \"404\": {{ \"description\": \"typed refusal\" }} }} }}");
    let collection = [get("", "#/components/schemas/List"), write("post", "", Some(format!("{{ \"$ref\": \"#/components/schemas/{}Create\" }}", c.name)))];
    let item = [
        write("delete", name_param, None),
        get(name_param, &format!("#/components/schemas/{}", c.name)),
        write("patch", name_param, Some("{ \"type\": \"object\", \"minProperties\": 1 }".into())),
        write("put", name_param, Some(format!("{{ \"$ref\": \"#/components/schemas/{}Replace\" }}", c.name))),
    ];
    format!(
        "{{\n  \"openapi\": \"3.1.0\",\n  \"info\": {{ \"title\": \"{unit} — generated {cls} API\", \"version\": \"0\", \"description\": \"Generated by athena-gen from the {cls} shape. Regenerate, never hand-edit (#4995).\" }},\n  \"paths\": {{\n    \"{base}\": {{ {coll} }},\n    \"{base}/{{name}}\": {{ {item} }}\n  }},\n  \"components\": {{ \"schemas\": {{\n    \"EdgeRef\": {{ \"type\": \"object\", \"properties\": {{ \"name\": {{ \"type\": \"string\" }}, \"label\": {{ \"type\": \"string\" }} }} }},\n    \"{cls}\": {{ \"type\": \"object\", \"properties\": {{ {props} }}{required} }},\n    \"{cls}Create\": {{ \"type\": \"object\", \"additionalProperties\": false, \"properties\": {{ {cp} }}, \"required\": [{cr}] }},\n    \"{cls}Replace\": {{ \"type\": \"object\", \"additionalProperties\": false, \"properties\": {{ {rp} }}, \"required\": [{rr}] }},\n    \"List\": {{ \"type\": \"object\", \"properties\": {{ \"count\": {{ \"type\": \"integer\" }}, \"data\": {{ \"type\": \"array\", \"items\": {{ \"$ref\": \"#/components/schemas/{cls}\" }} }} }} }}\n  }} }}\n}}\n",
        unit = esc(&p.name), cls = esc(&c.name), base = base, coll = collection.join(", "), item = item.join(", "),
        props = props.join(", "), required = required, cp = create_props.join(", "), cr = req(Some("name")),
        rp = replace_props.join(", "), rr = req(None)
    )
}

/// The page for one class: athena-make's generic entity page, pointed at the generated
/// API's port and collection route.
pub fn page_html(p: &Product, domain: &str, c: &Class, bind: &str) -> String {
    let port = bind.rsplit(':').next().unwrap_or("");
    let plural = crate::model::pluralize(&c.name).to_lowercase();
    format!(
        r##"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{cls} — Athena</title>
<!-- GENERATED by athena-gen (#4995) for the {unit} API. Regenerate from the model, never hand-edit. -->
<link rel="stylesheet" href="/css/system.css">
</head>
<body class="theme-light">
<nav class="navbar no-print">
  <a href="/athena/value-stream.html">Athena</a>
  <span class="muted">&rsaquo;</span> <a id="bc-step" href="#">Step</a>
  <span class="muted">&rsaquo;</span> <span id="bc-domain">{cls}</span>
</nav>
<div class="wrap">
  <h1 id="domain-title">{cls}</h1>
  <p class="muted" id="domain-subtitle"></p>
  <div class="content-actions" id="content-actions" data-title="Athena {cls}" data-url="">
    <button class="action-btn" data-btn="print" title="Save as PDF">&#x2913; PDF</button>
    <button class="action-btn" data-btn="share" title="Share this page">&#x2197; Share</button>
    <button class="action-btn" data-btn="reflect" title="Send to Reflect">&#x2726; Reflect</button>
  </div>
  <div id="stats-bar"></div>
  <div id="partof-block"></div>
  <div id="haschild-block"></div>
  <div id="promise-block"></div>
  <div id="completeness-block"></div>
  <div id="content-sections"></div>
  <p class="muted" style="margin-top:var(--space-5)">Athena &middot; Chorus &middot; GENERATED page (athena-gen) — live from the model</p>
</div>
<script>window.OWL_PORT = {port}; window.OWL_CLASS = "{cls}"; window.OWL_COLLECTION = "{plural}"; window.OWL_ROUTE = "{route}";</script>
<script src="https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js"></script>
<script src="/js/entity-renderer.js" defer></script>
<script src="/js/content-actions.js" defer></script>
</body>
</html>
"##,
        cls = c.name, unit = p.name, port = port, plural = plural, route = collection_route(p, domain, c)
    )
}

/// #5042 — the unit's launchd label: one per generated API.
pub fn unit_label(p: &Product) -> String {
    format!("com.chorus.{}-api", p.name)
}

/// #5042 — the Domain row that hosts the generated API (chorus:hosts is a Domain -> Service
/// edge; a Product has none). A domain's crate is hosted by that domain. A product's crate is
/// hosted by the first domain it owns, by name (Silas, 11-27 10:10: "awareness hosts pulse-api
/// ... a product reaches its services through the domains it composes"). None: it owns none.
pub fn host_of(p: &Product) -> Option<String> {
    if p.domain_unit {
        return Some(p.name.clone());
    }
    p.domains.iter().filter(|d| !d.composed).map(|d| d.name.clone()).min()
}

/// #5042 — the model facts that make the generated API a service (Silas, 11-25 11:16: "every
/// generated door is its own Service, hosted by the domain or product it is generated for"):
/// its Service row, the row that hosts it, and the launchd unit tied to it. Every text is made
/// from the model only (names, bind, classes), so a second generate writes the same file and
/// the model holds them once. The model holds them in designing/data/service-instances.ttl (the
/// Service row) and roles/silas/ontology/chorus.ttl (the hosts edge), loaded by the athena land;
/// tests/service_rows_in_model.rs holds the two equal (Silas, 11-27 12:09).
pub fn service_json(p: &Product, settings: &[(String, String)]) -> String {
    use serde_json::json;
    let bind = setting(settings, "server.bind");
    let name = format!("{}-api", p.name);
    let mut label: Vec<char> = p.name.replace('-', " ").chars().collect();
    if let Some(c) = label.first_mut() { *c = c.to_ascii_uppercase(); }
    let label: String = label.into_iter().collect();
    let classes: Vec<String> = p.domains.iter().filter(|d| !d.composed).flat_map(|d| d.classes.iter().map(|c| c.name.clone())).collect();
    let unit = unit_label(p);
    let host = host_of(p);
    let what = if p.domain_unit { "domain" } else { "product" };
    let text = serde_json::to_string_pretty(&json!({
        "unit": unit,
        "hostedBy": host.map(|h| json!({ "collection": "domains", "name": h, "hosts": format!("service-{name}") })),
        "service": {
            "name": name,
            "label": format!("{label} API"),
            "status": "operating",
            "docState": "current",
            "hasDesignDoc": "document-athena-product-design",
            "overview": format!("The {} {what}'s own API, generated by athena-gen from the model. It serves {} on {bind}; chorus-api's model door forwards it under /owl.", p.name, classes.join(", ")),
            "asIs": format!("Runs as the LaunchAgent {unit} through service-run, bound to {bind}. Each collection it owns serves its own OpenAPI document."),
            "toBe": "Every piece of it comes from the generator: the code, the launcher, the LaunchAgent, this row and its OpenAPI documents.",
            "gaps": "Its metrics, monitors and alerts are not generated yet (#5043).",
            "implementationPlan": "Generated code is never hand-edited: change athena-gen, regenerate, land.",
            "notInScope": "The pages that draw its data and the services that call it.",
            "pathToClose": "Closed when #5043 generates its metrics, monitors and alerts.",
        },
    }))
    .unwrap_or_default();
    text + "\n"
}

fn setting<'a>(settings: &'a [(String, String)], key: &str) -> &'a str {
    settings.iter().find(|(k, _)| k == key).map(|(_, v)| v.as_str()).unwrap_or("")
}

/// #5042 AC1 — the API's launch wrapper (crate-relative `<name>-api-launch.sh`), from its rows:
/// it hands the API the store credential by the NAMES its store.user_var / store.password_var
/// rows give, read key by key from the shared-infra file, never sourced whole, never printed.
pub fn launcher_sh(p: &Product, settings: &[(String, String)]) -> String {
    let name = format!("{}-api", p.name);
    let env = p.name.to_uppercase().replace('-', "_");
    let (user, pass) = (setting(settings, "store.user_var"), setting(settings, "store.password_var"));
    let domain = host_of(p).unwrap_or_else(|| p.name.clone());
    let unit = unit_label(p);
    format!(
        "#!/usr/bin/env bash\n\
         # @domain: {domain}\n\
         # {name} launch wrapper. Generated by athena-gen from the model (#5042) — DO NOT EDIT;\n\
         # change the generator. The LaunchAgent {unit} runs this from the repo. It hands {name}\n\
         # the store credential by NAME, as its settings rows say (store.user_var / store.password_var):\n\
         # the values come from the shared-infra file beside the store, extracted key by key, never\n\
         # sourced whole and never printed. Every other setting comes from the model (env {env}_<KEY>\n\
         # overrides, then {pn}.toml, then the row).\n\
         set -uo pipefail\n\
         _credenv=\"${{FUSEKI_WRITE_ENV:-$HOME/.gathering/data/fuseki-write.env}}\"\n\
         if [ -r \"$_credenv\" ]; then\n\
         \x20 export {pass}=\"$(grep -E '^{pass}=' \"$_credenv\" | head -1 | cut -d= -f2-)\"\n\
         \x20 export {user}=\"$(grep -E '^{user}=' \"$_credenv\" | head -1 | cut -d= -f2-)\"\n\
         \x20 [ -z \"${user}\" ] && export {user}=admin\n\
         fi\n\
         # reads need no credential; every write does, so say so at start rather than at the first 503\n\
         [ -n \"${{{pass}:-}}\" ] || echo \"{name}-launch: no {pass} from $_credenv — reads work, writes will be refused by the store\" >&2\n\
         # spine events through the team's logger on this box\n\
         export {env}_EVENTS_COMMAND=\"${{{env}_EVENTS_COMMAND:-$HOME/CascadeProjects/chorus/platform/scripts/chorus-log}}\"\n\
         exec \"${{{env}_API_BIN:-$HOME/.chorus/bin/{name}}}\" \"$@\"\n",
        pn = p.name,
    )
}

/// Every surface file for `p`, as (crate-relative path, text): surfaces/<Class>.{mcp.json,openapi.json,html}.
pub fn files(p: &Product, settings: &[(String, String)]) -> Vec<(String, String)> {
    let bind = setting(settings, "server.bind");
    let mut out = Vec::new();
    for d in p.domains.iter().filter(|d| !d.composed) {
        for c in &d.classes {
            out.push((format!("surfaces/{}.mcp.json", c.name), mcp_json(p, &d.name, c)));
            out.push((format!("surfaces/{}.openapi.json", c.name), openapi_json(p, &d.name, c)));
            out.push((format!("surfaces/{}.html", c.name), page_html(p, &d.name, c, bind)));
        }
    }
    out.push(("surfaces/service.json".to_string(), service_json(p, settings)));
    out
}
